export const narrations = {"ha-noi":{"name":"Hà Nội","voice":"Sulafat","model":"google/gemini-3.8-flash-tts","chapters":[{"id":"gioi-thieu","title":"Bức tranh miền đất","text":"Mặt hồ Hoàn Kiếm giữ một khoảng thoáng giữa nhịp phố Hà Nội. Quanh hồ, đường phố nối tiếp nhau; nhìn từ trên cao, mặt nước mở ra một nhịp chậm giữa những lớp mái nhà.\n\nTừ không gian ấy, câu chuyện đi về phố cổ, nơi tên phố còn gợi những nghề và những cuộc mua bán. Rồi đến Hoàng thành Thăng Long, Văn Miếu, những di tích và bảo tàng đang gìn giữ nhiều lớp ký ức.\n\nHà Nội có vẻ đẹp của sự đan xen: hồ nước bên phố xá, dấu xưa trong đời sống hôm nay. Một góc nhìn có thể bắt đầu từ Tháp Rùa, nhưng hành trình tìm hiểu còn mở xa hơn, qua lịch sử, văn hóa và những hương vị thường ngày của thủ đô.","sources":[{"id":"S03","title":"Hanoi: six heritage sites","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/hanoi-six-heritage-sites","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho tổng quan di tích, mốc Văn Miếu, Quốc Tử Giám và phố cổ. Loại chi tiết truyền thuyết và niên đại chưa đối chiếu thêm."},{"id":"S05","title":"11 must-see attractions in Ha Noi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Bài có chi tiết cần biên tập: nhầm vua xây chùa Một Cột, nhầm nhân vật truyền thuyết trả gươm; cách gọi 54 ethnic minorities không chính xác; giá và giờ không có mốc rõ. Đã loại các chi tiết này, chỉ lấy mô tả địa danh có căn cứ."},{"id":"S07","title":"Thư ngỏ – Hoàng thành Thăng Long","publisher":"Trung tâm Bảo tồn di sản Thăng Long – Hà Nội","url":"https://hoangthanhthanglong.vn/thu-ngo/","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn quản lý nêu khai quật khảo cổ năm 2002 và UNESCO năm 2010; dùng đối chiếu lịch sử và di sản."},{"id":"S04","title":"3 walking tours of Hanoi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/3-walking-tours-hanoi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho địa danh và tên món ăn; không lấy mô tả nguyên liệu phở cuốn trong bài. Tuyến đi bộ không được coi là hướng dẫn an toàn hay lịch hoạt động hiện hành."}],"src":"assets/audio/narration/ha-noi/gioi-thieu.mp3","duration":41.84,"script_sha256":"fb6c484c51308c4f63ae49573b6c4f6ac7840b9c4d4af8c97336492c8b9a0a35"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Giữa những tuyến phố nối nhau, hồ nước cho Hà Nội một khoảng thở. Hồ Hoàn Kiếm nằm trong khu vực trung tâm, gắn với đền Ngọc Sơn, cầu Thê Húc và không gian phố cổ lân cận.\n\nTừ trên cao, có thể nhìn thấy mối liên hệ giữa mặt hồ và các con đường bao quanh. Đổi một góc nhìn, hình dáng thành phố cũng đổi: khoảng nước trở thành điểm tựa để đọc nhịp điệu phố xá.\n\nCâu chuyện địa lý đô thị còn mở ra ở sông Hồng, cầu Long Biên và khu vực Trúc Bạch. Sông và hồ, cầu và phố, mỗi yếu tố góp một nét vào bức tranh Hà Nội. Những không gian ấy gợi nhiều tuyến khám phá, nối cảnh quan với đời sống của thành phố.","sources":[{"id":"S04","title":"3 walking tours of Hanoi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/3-walking-tours-hanoi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho địa danh và tên món ăn; không lấy mô tả nguyên liệu phở cuốn trong bài. Tuyến đi bộ không được coi là hướng dẫn an toàn hay lịch hoạt động hiện hành."},{"id":"S05","title":"11 must-see attractions in Ha Noi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Bài có chi tiết cần biên tập: nhầm vua xây chùa Một Cột, nhầm nhân vật truyền thuyết trả gươm; cách gọi 54 ethnic minorities không chính xác; giá và giờ không có mốc rõ. Đã loại các chi tiết này, chỉ lấy mô tả địa danh có căn cứ."}],"src":"assets/audio/narration/ha-noi/dia-ly.mp3","duration":41.12,"script_sha256":"8581723117cc02afdbc2d018154e502b9ea6517b1e8bd1fa07803c0d1b81a79c"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Thăng Long giữ ký ức bằng những lớp dấu tích nằm lại qua các triều đại. Hoàng thành là một điểm dừng để lần theo các lớp ấy, tìm hiểu lịch sử kinh đô qua tư liệu và di sản. Năm hai nghìn không trăm mười, di tích được UNESCO ghi danh.\n\nỞ một không gian khác, Văn Miếu và Quốc Tử Giám mở câu chuyện về truyền thống học tập. Văn Miếu có mốc xây dựng năm một nghìn không trăm bảy mươi; Quốc Tử Giám có mốc năm một nghìn không trăm bảy mươi sáu.\n\nNhững mốc thời gian làm lịch sử trở nên rõ ràng. Khi đặt chúng bên cảnh thành phố hôm nay, ta thấy một hành trình tiếp nối: di tích gìn giữ ký ức, còn đời sống hiện tại tiếp tục viết những trang riêng của Hà Nội.","sources":[{"id":"S03","title":"Hanoi: six heritage sites","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/hanoi-six-heritage-sites","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho tổng quan di tích, mốc Văn Miếu, Quốc Tử Giám và phố cổ. Loại chi tiết truyền thuyết và niên đại chưa đối chiếu thêm."},{"id":"S07","title":"Thư ngỏ – Hoàng thành Thăng Long","publisher":"Trung tâm Bảo tồn di sản Thăng Long – Hà Nội","url":"https://hoangthanhthanglong.vn/thu-ngo/","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn quản lý nêu khai quật khảo cổ năm 2002 và UNESCO năm 2010; dùng đối chiếu lịch sử và di sản."}],"src":"assets/audio/narration/ha-noi/lich-su.mp3","duration":38.56,"script_sha256":"da1ccd245fe452df45c7cd8c14c3fba5e7a6a3d7e5877cdd64672344f79ed1f7"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Hàng Bạc, Hàng Mã, Hàng Đường. Chỉ vài tên phố đã mở ra câu chuyện về nghề và buôn bán của Hà Nội. Tên gọi nằm trong đời sống thường ngày, nhưng cũng giữ một phần ký ức của phố cổ.\n\nTừ phố nghề, hành trình có thể đi đến Bảo tàng Dân tộc học Việt Nam, nơi giới thiệu đời sống văn hóa của nhiều cộng đồng trên cả nước. Mỗi không gian là một cách tìm hiểu con người: qua công việc, sinh hoạt và những điều được gìn giữ.\n\nRồi câu chuyện trở về với hương vị. Một bát phở, một tách cà phê trứng, phở cuốn hay phở chiên phồng gợi những cuộc khám phá khác giữa phố. Văn hóa Hà Nội hiện diện trong di sản, và cả trong những điều bình dị có thể gặp trên đường đi.","sources":[{"id":"S03","title":"Hanoi: six heritage sites","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/hanoi-six-heritage-sites","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho tổng quan di tích, mốc Văn Miếu, Quốc Tử Giám và phố cổ. Loại chi tiết truyền thuyết và niên đại chưa đối chiếu thêm."},{"id":"S05","title":"11 must-see attractions in Ha Noi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Bài có chi tiết cần biên tập: nhầm vua xây chùa Một Cột, nhầm nhân vật truyền thuyết trả gươm; cách gọi 54 ethnic minorities không chính xác; giá và giờ không có mốc rõ. Đã loại các chi tiết này, chỉ lấy mô tả địa danh có căn cứ."},{"id":"S04","title":"3 walking tours of Hanoi","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/3-walking-tours-hanoi","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cho địa danh và tên món ăn; không lấy mô tả nguyên liệu phở cuốn trong bài. Tuyến đi bộ không được coi là hướng dẫn an toàn hay lịch hoạt động hiện hành."}],"src":"assets/audio/narration/ha-noi/van-hoa.mp3","duration":44.52,"script_sha256":"83638595c11b9d052acd5c21c198cbbcfe4ed0e3898c0ca547f7f83978247b4e"}]},"lao-cai":{"name":"Lào Cai","voice":"Sulafat","model":"google/gemini-3.8-flash-tts","chapters":[{"id":"gioi-thieu","title":"Bức tranh miền đất","text":"Sa Pa mở ra giữa những lớp núi và khoảng trời rộng. Nhìn từ trên cao, phố xá nằm gọn trong cảnh quan; xuống gần mặt đất, nhà thờ đá, quảng trường và hồ Sa Pa trở thành những điểm dừng gần gũi.\n\nSun Plaza, khu chợ, những con đường nối các không gian sinh hoạt. Mỗi cảnh cho thấy một nét khác của trung tâm Sa Pa, nơi đời sống đô thị gặp cảnh sắc vùng cao.\n\nTừ đây, câu chuyện Lào Cai còn đi về Fansipan, Bắc Hà, những sườn ruộng Mù Cang Chải và khoảng nước hồ Thác Bà. Núi, ruộng và hồ mở ra nhiều dáng vẻ của vùng đất. Hành trình bắt đầu ở Sa Pa, rồi tiếp tục qua những miền cảnh quan và đời sống được kể trong sổ tay.","sources":[{"id":"S01","title":"Chi tiết 34 đơn vị hành chính cấp tỉnh","publisher":"Báo Điện tử Chính phủ","url":"https://xaydungchinhsach.chinhphu.vn/chi-tiet-34-don-vi-hanh-chinh-cap-tinh-tu-12-6-2025-119250612141845533.htm","displayed_date":"2026-10-05","accessed_on":"2026-10-06","status":"source_checked","note":"Dân số và diện tích Lào Cai là số liệu phục vụ sắp xếp năm 2025; không gọi là số liệu mới nhất năm 2026."},{"id":"S03","title":"Sapa","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/sapa","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cảnh quan, địa danh và chợ phiên; loại chiều cao Fansipan, thời gian cáp treo và thời gian di chuyển chưa đối chiếu. Mùa vụ và thời tiết là tham khảo, không phải dự báo."},{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/gioi-thieu.mp3","duration":41.56,"script_sha256":"aa21835dd3e7c11d5a27d4091d4bbc4ce9b7c82257a643a8210fcc7ea52a8dc7"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Núi và thung lũng tạo nên những lớp cảnh quan quanh Sa Pa. Ở Mù Cang Chải, ruộng bậc thang đi theo sườn núi, để đường nét của canh tác hòa vào địa hình.\n\nKhau Phạ là con đèo trong khu vực Mù Cang Chải, Tú Lệ. Câu chuyện về vùng cao vì thế có thêm những lối đi, nối nơi ở với những khoảng nhìn rộng hơn.\n\nHồ Thác Bà mở một nhịp khác: mặt nước của hồ nhân tạo hình thành cùng công trình thủy điện. Từ núi và ruộng đến hồ, cảnh quan Lào Cai cho thấy nhiều mối liên hệ giữa tự nhiên và hoạt động của con người. Mỗi không gian có một dáng vẻ riêng, và một câu chuyện riêng về cách sinh sống trên vùng đất ấy.","sources":[{"id":"S03","title":"Sapa","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/sapa","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Dùng cảnh quan, địa danh và chợ phiên; loại chiều cao Fansipan, thời gian cáp treo và thời gian di chuyển chưa đối chiếu. Mùa vụ và thời tiết là tham khảo, không phải dự báo."},{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/dia-ly.mp3","duration":39.16,"script_sha256":"d0b6dfed9cdc7dfbd288cd12bdb474574418d3eb8ad5b319578a4299657ac5fd"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Nhìn những thửa ruộng trên sườn núi, có thể đọc cảnh quan như một phần câu chuyện sinh kế. Đường nét của canh tác cho thấy cách con người làm việc cùng địa hình, để tạo nên không gian nông nghiệp của vùng cao.\n\nỞ hồ Thác Bà, cảnh quan lại gắn với công trình thủy điện. Sự hình thành hồ mở một lát cắt khác về mối liên hệ giữa hoạt động của con người và diện mạo vùng đất.\n\nSau sắp xếp năm hai nghìn không trăm hai mươi lăm, phạm vi tỉnh Lào Cai gồm Lào Cai và Yên Bái trước đây. Những tên địa phương trong tư liệu cũ vì thế cần được đọc cùng thời điểm xuất bản. Qua từng lát cắt, lịch sử dần được nối lại từ cảnh quan, sinh kế và các dấu mốc thay đổi.","sources":[{"id":"S01","title":"Chi tiết 34 đơn vị hành chính cấp tỉnh","publisher":"Báo Điện tử Chính phủ","url":"https://xaydungchinhsach.chinhphu.vn/chi-tiet-34-don-vi-hanh-chinh-cap-tinh-tu-12-6-2025-119250612141845533.htm","displayed_date":"2026-10-05","accessed_on":"2026-10-06","status":"source_checked","note":"Dân số và diện tích Lào Cai là số liệu phục vụ sắp xếp năm 2025; không gọi là số liệu mới nhất năm 2026."},{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/lich-su.mp3","duration":41.56,"script_sha256":"a34e9c3b53eed876610c38990d544336d8983e4c25a83adb735cc51c9f5831da"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Văn hóa vùng cao có thể được tìm hiểu từ một nếp nhà, một nghề thủ công, một bữa ăn. Tại Mù Cang Chải, tư liệu du lịch giới thiệu nghề dệt của người Mông. Câu chuyện nằm trong kỹ năng làm việc và những điều được cộng đồng gìn giữ.\n\nBên hồ Thác Bà, Ngòi Tu mở một không gian khác, gắn với nhà sàn, nghề đan và sinh hoạt của cộng đồng Dao. Mỗi nét văn hóa có nơi chốn riêng, cần được hiểu trong đời sống của cộng đồng ấy.\n\nCơm lam và gà nấu măng chua góp thêm câu chuyện về hương vị quanh hồ. Từ bàn tay làm nghề đến bữa ăn, hành trình khám phá trở nên gần gũi hơn: cảnh quan được nhìn thấy, còn đời sống được cảm nhận qua những điều bình dị.","sources":[{"id":"S04","title":"4 things you will love about Mu Cang Chai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/4-things-youll-love-about-mu-cang-chai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng địa danh tỉnh Yên Bái trước sắp xếp. Dùng mô tả cảnh quan và văn hóa; không dùng số giờ chạy xe hay lịch mùa vụ như cam kết hiện hành."},{"id":"S05","title":"Thac Ba Lake: the emerald of Yen Bai","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/things-to-do/thac-ba-lake-emerald-yen-bai","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn dùng Yên Bái và huyện Yên Bình/Lục Yên trước sắp xếp. Đã ánh xạ phạm vi tỉnh qua S01; loại xếp hạng hồ, số đảo và diện tích chưa đối chiếu; không khuyến nghị món cá sống."}],"src":"assets/audio/narration/lao-cai/van-hoa.mp3","duration":39.96,"script_sha256":"ad487b5642419183811efa27df6765e20c3d81c6b26f608a454dc30c3bd0626e"}]},"ninh-binh":{"name":"Ninh Bình","voice":"Sulafat","model":"google/gemini-3.8-flash-tts","chapters":[{"id":"gioi-thieu","title":"Bức tranh miền đất","text":"Giữa những dãy núi đá vôi trầm mặc, dòng nước Tràng An mở ra một khoảng xanh yên tĩnh. Núi soi bóng xuống sông, còn sông ôm lấy những thung lũng, nối hang động với những miền cây lá.\n\nTừ Hang Múa nhìn xuống, Tam Cốc hiện ra bằng đường cong của sông Ngô Đồng và những cánh đồng nằm giữa núi. Đi xa hơn trong câu chuyện của vùng đất, Hoa Lư giữ dấu kinh đô, Bái Đính mở ra không gian kiến trúc Phật giáo, còn Cúc Phương kể một câu chuyện khác bằng màu xanh của rừng.\n\nNinh Bình là nơi cảnh sắc và ký ức gặp nhau. Mỗi góc nhìn mở thêm một lớp non nước; mỗi điểm dừng đưa ta đến gần hơn với chiều sâu của vùng đất.","sources":[{"id":"S01","title":"Chi tiết 34 đơn vị hành chính cấp tỉnh","publisher":"Báo Điện tử Chính phủ","url":"https://xaydungchinhsach.chinhphu.vn/chi-tiet-34-don-vi-hanh-chinh-cap-tinh-tu-12-6-2025-119250612141845533.htm","displayed_date":"2026-10-05","accessed_on":"2026-10-06","status":"source_checked","note":"Bài dẫn Nghị quyết 202/2025/QH15. Số liệu diện tích và dân số là số liệu phục vụ sắp xếp năm 2025."},{"id":"S03","title":"Ninh Bình","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/vi/places-to-go/northern-vietnam/ninh-binh","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang ghi bản dịch được AI tạo. Chỉ lấy nội dung tổng quát; không dùng các kỷ lục, mùa vụ hay lịch vận chuyển như thông tin hiện hành chưa đối chiếu."},{"id":"S04","title":"Quần thể Danh thắng Tràng An – Bảo tàng địa chất ngoài trời","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3021","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Ngày trang hiển thị không bảo đảm mọi chi tiết nội dung vẫn nguyên bản tại ngày đó. Không lấy diện tích tổng quần thể làm diện tích vùng lõi UNESCO."},{"id":"S05","title":"Cố đô Hoa Lư","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3020","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Bài trộn địa chỉ mới trong phần đầu và địa chỉ cũ ở cuối. Giá vé cần xác nhận lại."},{"id":"S06","title":"Khám phá vẻ đẹp non nước hữu tình tại Khu du lịch Tam Cốc – Bích Động","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3116","displayed_date":"2025-06-26","accessed_on":"2026-10-06","status":"source_checked","note":"Thời lượng thuyền và mùa lúa là mô tả tham khảo; điều kiện thực tế có thể thay đổi."},{"id":"S07","title":"Vườn quốc gia Cúc Phương","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3018","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Nội dung hiện đọc nêu Ninh Bình, Phú Thọ, Thanh Hóa; địa chỉ cuối bài khác website vườn. Không tự suy ra cổng vào từ địa chỉ này."},{"id":"S10","title":"Hang Múa – kỳ quan thiên nhiên hùng vĩ của Ninh Bình","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3007","displayed_date":"2025-03-24","accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn ghi phường Hoa Lư; chưa xác nhận lại địa chỉ. Câu chuyện nguồn gốc tên gọi được ghi là câu chuyện dân gian."},{"id":"S16","title":"Website Vườn quốc gia Cúc Phương","publisher":"Vườn quốc gia Cúc Phương","url":"https://vuonquocgiacucphuong.vn/vi/","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Đã đọc trang chủ. Có thông báo quy định phương tiện vào vùng lõi áp dụng từ 1/9/2026; chưa đọc đầy đủ quy định, không tự diễn giải điều kiện."}],"src":"assets/audio/narration/ninh-binh/gioi-thieu.mp3","duration":42.88,"script_sha256":"60a8173a32acefc38d7bbdbb97b18422bc6c5e4d24d1cb5d319b82dbba67197e"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Núi ở Tràng An và Tam Cốc không đứng riêng lẻ. Những khối đá vôi nối nhau qua thung lũng, hang động và khoảng nước, tạo nên một cảnh quan vừa hùng vĩ, vừa mềm mại.\n\nSông Ngô Đồng đi qua ba hang của Tam Cốc, rồi uốn mình giữa những cánh đồng. Nhìn từ trên cao, dòng sông như một nét bút, còn núi đá là những khoảng lặng để nét bút ấy hiện lên rõ hơn.\n\nRời miền sông núi, Cúc Phương mở ra hệ sinh thái rừng. Về phía Kim Sơn, câu chuyện chuyển sang bãi bồi ven biển và nghề cói. Từ đá, nước đến rừng và bãi bồi, thiên nhiên Ninh Bình có nhiều dáng vẻ; mỗi dáng vẻ lại gắn với một cách con người sinh sống trên đất ấy.","sources":[{"id":"S04","title":"Quần thể Danh thắng Tràng An – Bảo tàng địa chất ngoài trời","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3021","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Ngày trang hiển thị không bảo đảm mọi chi tiết nội dung vẫn nguyên bản tại ngày đó. Không lấy diện tích tổng quần thể làm diện tích vùng lõi UNESCO."},{"id":"S06","title":"Khám phá vẻ đẹp non nước hữu tình tại Khu du lịch Tam Cốc – Bích Động","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3116","displayed_date":"2025-06-26","accessed_on":"2026-10-06","status":"source_checked","note":"Thời lượng thuyền và mùa lúa là mô tả tham khảo; điều kiện thực tế có thể thay đổi."},{"id":"S07","title":"Vườn quốc gia Cúc Phương","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3018","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Nội dung hiện đọc nêu Ninh Bình, Phú Thọ, Thanh Hóa; địa chỉ cuối bài khác website vườn. Không tự suy ra cổng vào từ địa chỉ này."},{"id":"S13","title":"Nghề cói Kim Sơn: Làng nghề truyền thống bên bãi bồi ven biển","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3663","displayed_date":"2026-07-28","accessed_on":"2026-10-06","status":"source_checked","note":"Kim Sơn ở đây là vùng văn hóa/nghề, không gán mọi cơ sở nghề vào xã Kim Sơn hiện hành."}],"src":"assets/audio/narration/ninh-binh/dia-ly.mp3","duration":41.28,"script_sha256":"15266e38ae8f50c4218d4efc67903094784b632ce23576390ad123a059a0afed"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Hoa Lư giữ một khoảng lặng sâu trong câu chuyện Ninh Bình. Giữa cảnh núi đá và thung lũng, dấu tích cố đô đưa ký ức trở về những buổi đầu của quốc gia độc lập.\n\nNăm chín trăm sáu mươi tám, Đinh Bộ Lĩnh lên ngôi. Hoa Lư gắn với các triều Đinh, Tiền Lê và đầu thời Lý. Đến năm một nghìn không trăm mười, Lý Thái Tổ dời đô về Thăng Long, mở một chương mới trong lịch sử kinh đô.\n\nHôm nay, đền thờ vua Đinh Tiên Hoàng và vua Lê Đại Hành vẫn là những điểm dừng để tìm hiểu các dấu mốc ấy. Lịch sử ở đây có thể được đọc qua tư liệu và di tích; cảnh non nước bao quanh làm cho hành trình tìm hiểu thêm phần sâu lắng.","sources":[{"id":"S05","title":"Cố đô Hoa Lư","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3020","displayed_date":"2025-03-27","accessed_on":"2026-10-06","status":"source_checked","note":"Bài trộn địa chỉ mới trong phần đầu và địa chỉ cũ ở cuối. Giá vé cần xác nhận lại."}],"src":"assets/audio/narration/ninh-binh/lich-su.mp3","duration":41.8,"script_sha256":"96b0263d52858c71924efb13df16ab9b4c5d318d0204eb9229f74f2133bedddd"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Văn hóa Ninh Bình đi qua cả những nghi lễ trang trọng và những công việc bình dị. Trong lễ hội Hoa Lư, rước nước, rước kiệu và dâng hương nối lòng tưởng nhớ hôm nay với các vị vua và tiền nhân.\n\nỞ Văn Lâm, đường kim, mũi chỉ làm nên câu chuyện thêu ren. Tại Kim Sơn, nghề cói kể về bàn tay khéo léo và sự gắn bó với sản vật của vùng đất. Bái Đính và Phát Diệm lại mở hai góc nhìn về kiến trúc tôn giáo, mỗi nơi một cách biểu đạt.\n\nCâu chuyện còn tiếp tục bên mâm cơm: cơm cháy, thịt dê, mắm tép Gia Viễn, nem chua Yên Mạc. Những tên gọi giữ hương vị địa phương, để một chuyến đi được nhớ bằng cả cảnh sắc và vị giác.","sources":[{"id":"S08","title":"Chùa Bái Đính","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3015","displayed_date":"2025-03-26","accessed_on":"2026-10-06","status":"source_checked","note":"Không đưa các tuyên bố kỷ lục vào dữ liệu đã duyệt khi chưa đọc xác nhận riêng."},{"id":"S09","title":"Nhà thờ đá Phát Diệm","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3014","displayed_date":"2025-03-26","accessed_on":"2026-10-06","status":"source_checked","note":"Dùng mô tả kiến trúc và khoảng thời gian xây dựng theo bài; xã Phát Diệm đối chiếu S02."},{"id":"S11","title":"Lễ hội Hoa Lư – Nơi lưu giữ nét đẹp truyền thống nghìn năm","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3359","displayed_date":"2025-09-24","accessed_on":"2026-10-06","status":"source_checked","note":"Lịch thường niên không thay thế thông báo tổ chức của từng năm."},{"id":"S12","title":"Làng nghề thêu ren Văn Lâm tinh hoa thủ công Ninh Bình","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3684","displayed_date":"2026-08-21","accessed_on":"2026-10-06","status":"source_checked","note":"Giới thiệu nghề; chưa xác nhận cơ sở nào có tour trải nghiệm đang mở."},{"id":"S13","title":"Nghề cói Kim Sơn: Làng nghề truyền thống bên bãi bồi ven biển","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3663","displayed_date":"2026-07-28","accessed_on":"2026-10-06","status":"source_checked","note":"Kim Sơn ở đây là vùng văn hóa/nghề, không gán mọi cơ sở nghề vào xã Kim Sơn hiện hành."},{"id":"S14","title":"Mắm tép Gia Viễn, đậm đà hương vị quê hương","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3719","displayed_date":"2026-09-14","accessed_on":"2026-10-06","status":"source_checked","note":"Thông tin văn hóa ẩm thực, không phải hướng dẫn bảo đảm an toàn thực phẩm."},{"id":"S15","title":"Nem chua Yên Mạc – Tinh hoa ẩm thực truyền thống của Ninh Bình","publisher":"Trung tâm Thông tin Xúc tiến Du lịch – Sở Du lịch Ninh Bình","url":"https://dulichninhbinh.com.vn/item/3718","displayed_date":"2026-09-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài cũng nhắc cơm cháy và thịt dê là đặc sản Ninh Bình; chưa xác minh giá hoặc cửa hàng."}],"src":"assets/audio/narration/ninh-binh/van-hoa.mp3","duration":41.2,"script_sha256":"cc3a4d6fc765ba06a9673e786bdb2e99db717e2b6e5d7fde553ec1d6f6075efa"}]},"quang-ninh":{"name":"Quảng Ninh","voice":"Sulafat","model":"google/gemini-3.8-flash-tts","chapters":[{"id":"gioi-thieu","title":"Bức tranh miền đất","text":"Giữa mênh mang biển, những đảo đá Hạ Long hiện lên như nét chạm khắc của thiên nhiên. Từ trên cao, khoảng nước mở rộng giữa các khối núi; xuống gần mặt vịnh, cảnh quan lại có một chiều sâu khác.\n\nNhững góc nhìn đưa câu chuyện qua đảo đá, hang động và hình ảnh làng chài. Cảnh sắc ấy gợi mối liên hệ lâu dài giữa con người với biển, giữa chỗ ở và hành trình mưu sinh.\n\nTừ Hạ Long, câu chuyện Quảng Ninh còn mở về Quan Lạn, Cô Tô, rồi lên miền núi Yên Tử. Biển đảo và núi rừng mang những dáng vẻ khác nhau, nhưng cùng làm nên một vùng đất có nhiều lớp cảnh quan và di sản để khám phá.","sources":[{"id":"S02","title":"Ha Long","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/ha-long","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Chỉ lấy mô tả cảnh quan và trải nghiệm tổng quát. Nội dung có nhắc điểm ngoài Quảng Ninh; đã loại khỏi hồ sơ. Không lấy lịch hoặc thời gian vận chuyển làm thông tin hiện hành."},{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."},{"id":"S06","title":"Bảo tàng – Thư viện thành phố","publisher":"Sở Văn hóa, Thể thao và Du lịch Quảng Ninh","url":"https://www.quangninh.gov.vn/so/sovanhoathethao/trang/chitietbvgioithieu.aspx?bvid=84","displayed_date":"2026-09-04","accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn về chức năng và nhiệm vụ đơn vị, không phải hướng dẫn trưng bày hoặc giá vé. Không nhập thông tin cá nhân cán bộ vào database du lịch."},{"id":"S03","title":"Co To Island: pristine beauty of Northeast Vietnam","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://www.vietnam.travel/vi/things-to-do/co-island-pristine-beauty-northeast-vietnam","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang tiếng Việt ghi bản dịch do AI tạo. Chỉ lấy mô tả địa danh tổng quát; loại số liệu, niên đại hải đăng và quy định hạn chế nhựa chưa đối chiếu."},{"id":"S04","title":"Discovering the beauty of Quan Lan Island","publisher":"Cục Du lịch Quốc gia Việt Nam – TITC","url":"https://vietnamtourism.gov.vn/en/post/9785","displayed_date":"2015-11-09","accessed_on":"2026-10-06","status":"source_checked","note":"Bài năm 2015 dùng địa danh huyện Vân Đồn trước sắp xếp. Không nhập số lượng phòng, cơ sở lưu trú, lịch tàu, giá hay thời gian chạy tàu như hiện hành."}],"src":"assets/audio/narration/quang-ninh/gioi-thieu.mp3","duration":35.88,"script_sha256":"53bd35eadb24fa5e56e7d921f8bdfb0513cba75d41ce4429094850ef632b7688"},{"id":"dia-ly","title":"Địa lý & cảnh quan","text":"Hạ Long được nhận ra bằng núi đá vôi giữa biển. Những khối núi có hình dáng khác nhau, còn khoảng nước giữa chúng tạo nên những lối nhìn luôn thay đổi.\n\nTừ trên cao, cảnh quan hiện ra thành một bức tranh rộng. Khi hạ xuống gần mặt nước, các khối đá trở nên gần gũi hơn, và hành trình có thêm những chi tiết để quan sát.\n\nQuan Lạn nằm trong vịnh Bái Tử Long. Cô Tô mở câu chuyện qua bãi biển, bờ đá và đảo Thanh Lân. Xa không gian biển đảo, Yên Tử lại có cảnh quan núi rừng. Quảng Ninh vì thế có nhiều nhịp điệu của thiên nhiên: khoảng rộng của biển, đường nét của đảo và chiều sâu của núi.","sources":[{"id":"S02","title":"Ha Long","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://vietnam.travel/places-to-go/northern-vietnam/ha-long","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Chỉ lấy mô tả cảnh quan và trải nghiệm tổng quát. Nội dung có nhắc điểm ngoài Quảng Ninh; đã loại khỏi hồ sơ. Không lấy lịch hoặc thời gian vận chuyển làm thông tin hiện hành."},{"id":"S03","title":"Co To Island: pristine beauty of Northeast Vietnam","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://www.vietnam.travel/vi/things-to-do/co-island-pristine-beauty-northeast-vietnam","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang tiếng Việt ghi bản dịch do AI tạo. Chỉ lấy mô tả địa danh tổng quát; loại số liệu, niên đại hải đăng và quy định hạn chế nhựa chưa đối chiếu."},{"id":"S04","title":"Discovering the beauty of Quan Lan Island","publisher":"Cục Du lịch Quốc gia Việt Nam – TITC","url":"https://vietnamtourism.gov.vn/en/post/9785","displayed_date":"2015-11-09","accessed_on":"2026-10-06","status":"source_checked","note":"Bài năm 2015 dùng địa danh huyện Vân Đồn trước sắp xếp. Không nhập số lượng phòng, cơ sở lưu trú, lịch tàu, giá hay thời gian chạy tàu như hiện hành."},{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."}],"src":"assets/audio/narration/quang-ninh/dia-ly.mp3","duration":41.08,"script_sha256":"2075574acb22e227767fd8abb1bfb5963e6ad26fe8f9bdd8f3b9644350c46eb7"},{"id":"lich-su","title":"Lịch sử & di sản","text":"Trên miền núi Yên Tử, câu chuyện lịch sử đi cùng chùa, am và tháp. Các công trình nằm trong cảnh quan núi rừng, tạo nên một hành trình vừa tìm hiểu kiến trúc, vừa tìm hiểu ký ức Phật giáo.\n\nYên Tử gắn với Trần Nhân Tông và Thiền phái Trúc Lâm. Những tên gọi ấy mở một lớp di sản khác của Quảng Ninh, bên cạnh cảnh sắc biển đảo thường được biết đến.\n\nNăm hai nghìn không trăm mười hai, khu di tích được xếp hạng quốc gia đặc biệt. Dấu mốc ấy thuộc câu chuyện bảo tồn và nhận diện giá trị di tích. Nhìn về Yên Tử, hành trình khám phá có thêm một khoảng sâu lắng, nơi cảnh quan và lịch sử cùng được đọc qua những điều còn được gìn giữ.","sources":[{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."}],"src":"assets/audio/narration/quang-ninh/lich-su.mp3","duration":43.8,"script_sha256":"8dbb9826d39c087e3f738aac430900a3d9d025c88aa0d54fa17eb8350391ed40"},{"id":"van-hoa","title":"Văn hóa & ẩm thực","text":"Biển đảo Quảng Ninh có cả cảnh đẹp và những câu chuyện văn hóa. Trên Quan Lạn, cụm đình, đền, chùa mở một lối tìm hiểu di sản giữa hành trình khám phá đảo. Ở Yên Tử, chùa, am và tháp lại gắn với sinh hoạt Phật giáo.\n\nBảo tàng, Thư viện Quảng Ninh góp phần lưu giữ và giới thiệu ký ức địa phương. Mỗi điểm dừng đưa người xem đến gần một cách sống, một không gian sinh hoạt và một phần câu chuyện của vùng đất.\n\nHương vị biển cũng có chỗ trong hành trình ấy. Mực, hàu, bề bề và sá sùng được nhắc đến trong tư liệu giới thiệu Cô Tô. Từ cảnh quan đến bàn ăn, việc khám phá đi qua nhiều giác quan, để ký ức về một vùng biển trở nên phong phú hơn.","sources":[{"id":"S04","title":"Discovering the beauty of Quan Lan Island","publisher":"Cục Du lịch Quốc gia Việt Nam – TITC","url":"https://vietnamtourism.gov.vn/en/post/9785","displayed_date":"2015-11-09","accessed_on":"2026-10-06","status":"source_checked","note":"Bài năm 2015 dùng địa danh huyện Vân Đồn trước sắp xếp. Không nhập số lượng phòng, cơ sở lưu trú, lịch tàu, giá hay thời gian chạy tàu như hiện hành."},{"id":"S05","title":"Khu di tích lịch sử và danh lam thắng cảnh Yên Tử","publisher":"Cổng thông tin điện tử Quảng Ninh","url":"https://www.quangninh.gov.vn/Trang/ChiTietBVGioiThieu.aspx?bvid=530","displayed_date":"2025-07-14","accessed_on":"2026-10-06","status":"source_checked","note":"Bài nêu địa giới phường sau sắp xếp và sự kiện UNESCO ngày 12/07/2025. Chỉ lấy phần di tích Quảng Ninh, không mở rộng hồ sơ sang Bắc Ninh hoặc Hải Phòng."},{"id":"S06","title":"Bảo tàng – Thư viện thành phố","publisher":"Sở Văn hóa, Thể thao và Du lịch Quảng Ninh","url":"https://www.quangninh.gov.vn/so/sovanhoathethao/trang/chitietbvgioithieu.aspx?bvid=84","displayed_date":"2026-09-04","accessed_on":"2026-10-06","status":"source_checked","note":"Nguồn về chức năng và nhiệm vụ đơn vị, không phải hướng dẫn trưng bày hoặc giá vé. Không nhập thông tin cá nhân cán bộ vào database du lịch."},{"id":"S03","title":"Co To Island: pristine beauty of Northeast Vietnam","publisher":"Vietnam Tourism – Cục Du lịch Quốc gia Việt Nam","url":"https://www.vietnam.travel/vi/things-to-do/co-island-pristine-beauty-northeast-vietnam","displayed_date":null,"accessed_on":"2026-10-06","status":"source_checked","note":"Trang tiếng Việt ghi bản dịch do AI tạo. Chỉ lấy mô tả địa danh tổng quát; loại số liệu, niên đại hải đăng và quy định hạn chế nhựa chưa đối chiếu."}],"src":"assets/audio/narration/quang-ninh/van-hoa.mp3","duration":44.64,"script_sha256":"07d13e9d55cbfa0a0b08caaad93d3788f32ed6b06d10f7c7596594f17423d457"}]}};
